#include <stdio.h>

int main(void) {
    int V, A, F, P;
    if (scanf("%d %d %d %d", &V, &A, &F, &P) != 4) return 0;

    int c[3] = {A, F, P};

    for (int i = 0; i < 2; i++) {
        for (int j = i + 1; j < 3; j++) {
            if (c[i] > c[j]) {
                int temp = c[i];
                c[i] = c[j];
                c[j] = temp;
            }
        }
    }

    int ans = 0;
    for (int i = 0; i < 3; i++) {
        if (V >= c[i]) {
            V -= c[i];
            ans++;
        } else {
            break;
        }
    }

    printf("%d\n", ans);
    return 0;
}
